import numpy as np
from scipy.optimize import minimize

def solve_quadratic_program(P, q, G, h, A=None, b=None):
    n = len(q)

    def objective(x):
        return 0.5 * x @ P @ x + q @ x

    def gradient(x):
        return P @ x + q

    constraints = []
    for i in range(len(h)):
        constraints.append({
            'type': 'ineq',
            'fun': lambda x, i=i: h[i] - G[i] @ x
        })

    if A is not None and b is not None:
        for j in range(len(b)):
            constraints.append({
                'type': 'eq',
                'fun': lambda x, j=j: A[j] @ x - b[j]
            })

    x0 = np.zeros(n)
    result = minimize(objective, x0, jac=gradient, constraints=constraints, method='SLSQP')

    return result

P = np.array([[2, 0], [0, 2]])
q = np.array([0, 0])
G = np.array([[-1, -1]])
h = np.array([-1])

result = solve_quadratic_program(P, q, G, h)
print(f"Optimal solution: {result.x}")
print(f"Optimal value: {result.fun}")
